// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 newBetLimit, address player, uint256 betAmount) public {
        // Ensure newBetLimit is reasonable and betAmount is exactly that limit
        vm.assume(newBetLimit > 0 && newBetLimit <= 1e18);
        vm.assume(betAmount == newBetLimit);

        // Open to public and set the bet limit
        c.OpenToThePublic();
        c.AdjustBetAmounts(newBetLimit);

        // Prepare the player
        vm.deal(player, betAmount);

        // Try to wager with msg.value = betAmount (which equals newBetLimit)
        vm.prank(player, player);
        (bool success, ) = address(c).call{value: betAmount}(abi.encodeWithSignature("wager()"));

        assertTrue(success, "wager should succeed when msg.value equals betLimit");
    }
}

